    create_template_context = _k.Attr(2002, 'create_template_context')
    func = _k.Attr(2003, 'func')
    gcode = _k.Attr(2004, 'gcode')
    gcode_macro = _k.Attr(2005, 'gcode_macro')
    name = _k.Attr(2006, 'name')
